import "server-only";
import { prisma } from "@formbricks/database";
import type { OrganizationRole } from "@formbricks/database/prisma";
import type { TUserNotificationSettings } from "@formbricks/types/user";

export type TAccountDataExport = {
  name: string;
  email: string;
  locale: string;
  notificationSettings: TUserNotificationSettings;
  organizations: { name: string; role: OrganizationRole }[];
};

/**
 * The personal data held on a user, for the "Download my data" export. Pending invitations are not
 * memberships, so only accepted ones are listed. Returns null when the user no longer exists.
 */
export const getAccountDataExport = async (userId: string): Promise<TAccountDataExport | null> => {
  const user = await prisma.user.findUnique({
    where: { id: userId },
    select: {
      name: true,
      email: true,
      locale: true,
      notificationSettings: true,
      memberships: {
        where: { accepted: true },
        select: { role: true, organization: { select: { name: true } } },
        orderBy: { organization: { name: "asc" } },
      },
    },
  });

  if (!user) return null;

  return {
    name: user.name,
    email: user.email,
    locale: user.locale,
    notificationSettings: user.notificationSettings as TUserNotificationSettings,
    organizations: user.memberships.map((membership) => ({
      name: membership.organization.name,
      role: membership.role,
    })),
  };
};
EOF
cat > apps/web/app/api/v3/account/data/lib/operations.ts <<'EOF'
import "server-only";
import { problemForbidden, successResponse } from "@/app/api/v3/lib/response";
import { problemInternalError } from "@/app/api/v3/lib/response";
import type { TV3Authentication } from "@/app/api/v3/lib/types";
import { getV3SessionUserId } from "@/app/api/v3/lib/auth";
import { getAccountDataExport } from "@/modules/account/lib/account-data-export";

export const ACCOUNT_DATA_FILE_NAME = "formbricks-account-data.json";

/**
 * The signed-in user's own data. The user is always the session's, never a client-supplied id, so
 * nobody can export another account.
 */
export async function getV3AccountData(params: {
  authentication: TV3Authentication;
  requestId: string;
  instance?: string;
}): Promise<Response> {
  const { authentication, requestId, instance } = params;

  const userId = getV3SessionUserId(authentication);
  if (!userId) {
    return problemForbidden(requestId, "You are not authorized to access this resource", instance);
  }

  const data = await getAccountDataExport(userId);
  if (!data) {
    return problemInternalError(requestId, "Unable to export account data", instance);
  }

  const response = successResponse(data, { requestId });
  response.headers.set("Content-Disposition", `attachment; filename="${ACCOUNT_DATA_FILE_NAME}"`);
  return response;
}
EOF
cat > apps/web/app/api/v3/account/data/route.ts <<'EOF'
/**
 * GET /api/v3/account/data - the signed-in user's own data (name, email, locale, notification settings
 * and organization memberships), sent as a JSON attachment for the "Download my data" button.
 *
 * Session-only, deliberately: it exports the personal data of the session's user, so an API key has no
 * user to export.
 */
import { withV3ApiWrapper } from "@/app/api/v3/lib/api-wrapper";
import { getV3AccountData } from "./lib/operations";

export const GET = withV3ApiWrapper({
  auth: "session",
  handler: async ({ authentication, requestId, instance }) =>
    getV3AccountData({ authentication, requestId, instance }),
});
EOF
